"""Assemble IMPLEMENTATION_REPORT.md and verification-results.json from the recorded runs (no numbers are typed by hand)."""
import json, subprocess, sys
from pathlib import Path
A = Path(sys.argv[1]); run = json.load(open(sys.argv[2])); bench = json.load(open(A / 'benchmarks' / 'native-benchmark.json')); units = (A / 'logs' / 'unit-suites-final.log').read_text()
ce = json.load(open(sys.argv[3])) if len(sys.argv) > 3 and Path(sys.argv[3]).exists() else None
by = {r['journey']: r for r in run['results']}; j21 = by[21]['evidence']; j19 = by[19]['evidence']; j12 = by[12]['evidence']; j18 = by[18]['evidence']
head = subprocess.run(['git', 'rev-parse', 'HEAD'], capture_output=True, text=True).stdout.strip(); base = (A / 'BASE_REVISION.txt').read_text().strip()
start = Path('work/native-space-protocol-session/START').read_text().strip()
suites = [l.strip() for l in units.splitlines() if ': Ran' in l]
vr = {'schema': 'metacoin-native-verification-results/v1', 'source_revision': head, 'base_revision': base, 'journeys': {k: run[k] for k in ('passed', 'failed', 'blocked', 'total', 'revision')}, 'journey_statuses': {r['journey']: r['status'] for r in run['results']},
      'unit_suites': suites, 'unit_suites_all_ok': all('OK' in l and 'FAILED' not in l for l in suites), 'benchmark': {k: bench[k] for k in ('transfers', 'settlement', 'journal_replay', 'recovery_sweep', 'storage_bytes', 'economic_summary')}, 'clean_export': ({k: ce.get(k) for k in ('passed', 'failed', 'blocked', 'total', 'archive_sha256')} if ce else None),
      'browser': by[38]['evidence'].get('checks') if by[38]['status'] == 'passed' else by[38], 'skipped_or_blocked': [{'journey': r['journey'], 'status': r['status'], 'reason': r['evidence'].get('blocked')} for r in run['results'] if r['status'] != 'passed']}
json.dump(vr, open(A / 'verification-results.json', 'w'), indent=1)
R = []
R.append('# Implementation report — MetaCoin native space-work and settlement protocol (order 2026-10-22)\n')
R.append('## The demonstrated native economic cycle (journey 21, real processes, x402 disabled, facilitator blocked)\n')
R.append('Requester fixture-funded with 80 units of the zero-value development asset; every other account started at zero. A real route-feasibility task on the Apollo 11 LOLA LDEM_4 extract was computed by the worker, verified by the independent lunar reference, accepted under frozen terms and settled natively: machine 40, verifier 3, treasury 2 (fees additional to the 40), requester kept 35. Before earning, the machine\'s purchase was refused (`%s`). The machine then bought a distinct computation for 10 from its earned balance (supplier 9, treasury 1), and the treasury reserved and paid a 2-unit award through ordinary work acceptance. Final balances %s, total %d. Authority consumed: 45 reserved then released to 35 on the requester; 10 on the machine; 2 on the treasury. Nothing minted; audit conserved.\n' % (j21.get('purchase_before_earning'), json.dumps(j21.get('final')), j21.get('total', 0)))
R.append('Across domains (journeys 8–20): exports locked backing before any certificate; imports credited once (duplicates idempotent, acks replayed); a lost acknowledgment left the backing locked (no refund, no re-export); every export/import crash boundary recovered without duplicated ownership (held across both domains = fixture: %s); preallocated authority supported bounded spending across a cut link with file bundles; a full unspent return closed through the reverse protocol and a partial return was refused; a conflicting signed history quarantined the peer; a backup restore entered quarantine (`%s`) and left it only after the peer\'s signed observation reconstructed the missing allocation as locked backing.\n' % (j12.get('held_both') == j12.get('fixture'), j19.get('after_restore')))
R.append('## Revisions and time\n- Base: `%s` (evidence/acquisition-assurance records commit; source candidate 7159389)\n- Source candidate: `%s` on branch `protocol/native-space-settlement-v0` (not pushed; GitHub and live main unchanged)\n- Loaded revision in the journeys: `%s`; live service: 3e34126 / schema 040, untouched\n- Started %s; this report built at %s\n' % (base, head, run.get('revision'), start, __import__('datetime').datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')))
R.append('## Verification\n- Forty journeys (`journeys/journeys-native-run5.json`): %d passed, %d failed, %d blocked (%s).\n- Unit suites on the candidate: %s.\n- Browser (journey 38): %s checks passed, screenshots in `browser-screenshots/`.\n- Benchmark (`benchmarks/native-benchmark.json`): %d concurrent transfers p50 %.3fs p95 %.3fs, %.0f/s, all correct; native vs application-journal settlement on identical workloads: pay p50 %.3fs vs %.3fs, awards accepted %d/%d vs %d/%d; journal replay %.3fs consistent; storage %d bytes.\n- Clean export (journey 39): %s.\n' % (run['passed'], run['failed'], run['blocked'], '; '.join('%d %s: %s' % (x['journey'], x['status'], x['reason']) for x in vr['skipped_or_blocked']) or 'none', 'all OK' if vr['unit_suites_all_ok'] else 'see logs', by[38]['evidence'].get('passed'), bench['transfers']['count'], bench['transfers']['p50_s'], bench['transfers']['p95_s'], bench['transfers']['throughput_per_s'], bench['settlement']['native']['pay_p50_s'], bench['settlement']['application_journal']['pay_p50_s'], bench['settlement']['native']['awards'] - bench['settlement']['native']['failed_or_unaccepted'], bench['settlement']['native']['awards'], bench['settlement']['application_journal']['awards'] - bench['settlement']['application_journal']['failed_or_unaccepted'], bench['settlement']['application_journal']['awards'], bench['journal_replay']['seconds'], bench['storage_bytes']['service_sqlite'], ('%s passed / %s failed on archive %s' % (ce.get('passed'), ce.get('failed'), (ce.get('archive_sha256') or '')[:16])) if ce else 'not yet recorded'))
R.append('## What settled where\n- Locally (domain-local settlement): every work payment and transfer in both domains carries a commit sequence and an authority receipt.\n- Across domains: allocations acknowledged after the courier round trip (reconciled inter-domain settlement); at the end of the run the audit of domain A reported backing %s against domain B claims %s (pending backing not yet imported: %s).\n- Treasury: funded only by settled fees; awards reserve from the treasury account; over-allocation and duplicate allocation refused (journey 31).\n' % (j18.get('A', {}).get('backing_locked_for_exports'), j18.get('B', {}).get('claims_backed_elsewhere'), j18.get('pending_backing_not_yet_imported')))
R.append('## Required failures, skips and caveats\n- Journey 39 is recorded from the clean export run, not inside the main run.\n- Same operator and host for both domains; development keys service-custodied; equivocation detected not prevented; rollback detection needs the watermark file or a peer observation; returns full-and-unspent only; application-level transport (not BPv7).\n- Lunar products are grid-scale (7.58 km/pixel); tiles ≤ 64×64; no GPU path; evidence-acquisition deliveries are simulated.\n- Live service not upgraded; branch not pushed.\n## Remaining extensions (§22)\nNone of the ten prioritized extensions was started; the required groups consumed the session.\n')
open(A / 'IMPLEMENTATION_REPORT.md', 'w').write('\n'.join(R)); print('report built', head[:8], run['passed'], run['failed'], run['blocked'])
